--条件判断
function Melter_Judge(nCostType, nValue, nMonopoly, nTen, nNowUserId)
	local nUserId = nNowUserId or Get_UserId()
	local nNum = 1
	
	if nTen == 1 then
		nNum = 10
	end
	
	--判断是否无赠品服务器
	-- if SpecialServer_ChkNoGiftServer() then
		-- --判断奖励表的数据是否存在
		-- if tMelter_Info_NoGift["Reword"][nCostType] == nil or tMelter_Info_NoGift["Reword"][nCostType][nValue] == nil then
			-- return false
		-- end
	-- else
		--判断奖励表的数据是否存在
		if tMelter_Info["Reword"][nCostType] == nil or tMelter_Info["Reword"][nCostType][nValue] == nil then
			return false
		end
	-- end
	
	--判断消耗物品是否充足使用的函数是否存在
	if tMelter_List[nCostType]["LimitFunc"] == nil then
		return false
	end
	
	local nAfterMonopoly = 0
	
	if nMonopoly ~= 0 then
		nAfterMonopoly = 2
	end
	
	--判断消耗物品是否充足
	if nCostType == 8 then
		if not tMelter_List[nCostType]["LimitFunc"](nValue, nNum, nAfterMonopoly, nUserId) then
			return false
		end
	else
		if not tMelter_List[nCostType]["LimitFunc"](nValue, nNum, nUserId) then
			return false
		end
	end
	
	--判断消耗物品使用的函数是否存在
	if tMelter_List[nCostType]["Func"] == nil then
		return false
	end
	
	local nLogId = tMelter_Cont["LogId"]
	
	--扣除相应物品或条件
	if nCostType == 8 then
		--扣除金币
		if tMelter_Money[nValue] ~= nil then
			if not User_CanPutMoney2Bag(-(tMelter_Money[nValue] * nNum),nUserId) then
				return false
			end
			
			if not User_AddMoney(-(tMelter_Money[nValue] * nNum),nUserId) then
				return false
			end
		end
		
		if not Item_DelMulItem(nValue,nValue,nNum,nAfterMonopoly,nil,nUserId) then
			User_TalkChannel2005(tRewardTemplate_Text["Consume"]["DeleteItem"],nUserId)
			return false
		end
		
		local sLog = string.format("0,0,%d,%d,%d,2,0,0", nValue, nNum, nLogId)
		Sys_SaveActionRewardLog(sLog,nUserId)
		-- 贵重物品统计
		if (nValue >= 4200001 and nValue <= 4200019) then
			Sys_DecNosuchStatisticCount(356,nValue,nNum)
		end
		
		--判断是否有活动时间
		if tMelter_Info["Reword"][nCostType][nValue]["ActivityTime"] ~= nil then
			if not Sys_ChkFullTime(tMelter_Info["Reword"][nCostType][nValue]["ActivityTime"]) then
				Sys_MsgBox(tLuaRes[10004], nil,nil,nUserId)
				return false
			end
		end
	else
		if not tMelter_List[nCostType]["Func"](-(nValue * nNum)) then
			User_TalkChannel2005(tMelter_Text["Consume"][nCostType],nUserId)
			return false
		end
	end
	
	return true
end

--权重概率计算
function Melter_RandomCompute(tAward, tPreciousIndex, nCount, nNowUserId)
	local nUserId = nNowUserId or Get_UserId()
	
	--保存每个物品的概率调整后的数值
	local tAwardChange = {}
	
	--贵重物品几率表为空，直接返回初始值
	if next(tPreciousIndex) == nil then
		for i = 1, nCount do
			tAwardChange[i] = tAward[i]["ItemChance"]
		end
		
		return tAwardChange
	end
	
	--贵重物品调整后的概率值修正
	local tNowPreciousIndex = {}
	
	for k,v in pairs(tPreciousIndex) do
		if v <= 0 then
			tNowPreciousIndex[k] = 0
		elseif v >= tAward["ItemChanceSum"] then
			tNowPreciousIndex[k] = tAward["ItemChanceSum"]
		else
			tNowPreciousIndex[k] = v
		end
	end
	
	local tMustGet = {}
	
	--判断是否有配必定出的奖励
	for k,v in pairs(tAward) do
		if type(v) == "table" then
			if v["MustNum"] ~= nil then
				tMustGet[k] = {}
				tMustGet[k]["MustNum"] = v["MustNum"]
				tMustGet[k]["MustPro"] = v["MustPro"]
			end
		end
	end
	
	--必定出的次数达到则概率调整为100%，直接返回
	if next(tMustGet) ~= nil and tAward["StcEvent"] ~= nil and tAward["StcType"] ~= nil then
		local nEvent = tAward["StcEvent"]
		local nType = tAward["StcType"]
		local nData = Get_UserStatisticValue(nEvent,nType,nUserId) + 1
		local nPro = math.floor(Get_UserProfession(nUserId) / 10)
		
		--保存必定出的奖励索引
		local nMustIndex = 0
		
		for k,v in pairs(tMustGet) do
			--次数达到
			if nData == v["MustNum"] then
				--是否有职业需求
				if v["MustPro"] == nil then
					nMustIndex = k
					break
				elseif nPro == v["MustPro"] then
					nMustIndex = k
					break
				end
			end
		end
		
		if nMustIndex ~= 0 then
			for i = 1, nCount do
				if nMustIndex == i then
					tAwardChange[i] = tAward["ItemChanceSum"]
				else
					tAwardChange[i] = 0
				end
			end
			
			return tAwardChange
		end
	end
	
	--贵重物品几率与调整值的差值
	local nItemChanceSub = 0
	--贵重物品总概率
	local nTotalPreciousChance = 0
	--贵重物品种类数量
	local nPreciousNum = 0
	
	for k,v in pairs(tNowPreciousIndex) do
		nItemChanceSub = nItemChanceSub + tAward[k]["ItemChance"] - v
		nTotalPreciousChance = nTotalPreciousChance + v
		nPreciousNum = nPreciousNum + 1
	end
	
	--如果概率没有变化，则直接返回初始值
	if nItemChanceSub == 0 then
		for i = 1, nCount do
			tAwardChange[i] = tAward[i]["ItemChance"]
		end
		
		return tAwardChange
	end
	
	--如果贵重物品概率加起来大于100%，则消除多于的概率值
	if nTotalPreciousChance > tAward["ItemChanceSum"] then
		local nLeft = nTotalPreciousChance - tAward["ItemChanceSum"]
		local nPreciousChance = nLeft / nPreciousNum
		local nEveryPreciousChange = math.floor(nPreciousChance)
		local nPreciousChangeLeft = 0
		--取整后丢失的值
		if nPreciousChance % 1 ~= 0 then
			nPreciousChangeLeft = nLeft - nPreciousNum * nEveryPreciousChange
		end
		
		for i = 1, nCount do
			local bPreciousFlag = false
			local nNowPreciousChange = 0
			
			--判断当前索引是不是贵重物品
			for k,v in pairs(tNowPreciousIndex) do
				if k == i then
					bPreciousFlag = true
					nNowPreciousChange = v
					break
				end
			end
			
			if bPreciousFlag then
				if nPreciousChangeLeft > 0 then
					tAwardChange[i] = nNowPreciousChange - nEveryPreciousChange - nPreciousChangeLeft
					nPreciousChangeLeft = 0
				else
					tAwardChange[i] = nNowPreciousChange - nEveryPreciousChange
				end
			else
				tAwardChange[i] = 0
			end
		end
		
		return tAwardChange
	end
	
	--计算可以分配的概率值
	local nChangeResult = nItemChanceSub / (nCount - nPreciousNum)
	--概率值取整
	local nEveryChange = math.floor(nChangeResult)
	--计算取整后丢失的值
	local nChangeLeft = 0
	
	if nChangeResult % 1 ~= 0 then
		nChangeLeft = nItemChanceSub - (nCount - nPreciousNum) * nEveryChange
	end
	
	--临时数据表
	local tData = {}
	--临时概率表
	local tChange = {}
	
	--复制当前概率表到临时表
	for i = 1, nCount do
		tChange[i] = tAward[i]["ItemChance"]
	end
	
	--循环遍历临时概率表，冒泡排序，从小到大，保存到tData表
	for i = 1, nCount do
		local nDataChance = tAward["ItemChanceSum"]
		local nDataIndex = 0
		
		for k,v in pairs(tChange) do
			local bFlag = true
			
			--判断表内是否有数据
			if next(tData) ~= nil then
				for m,n in pairs(tData) do
					--判断数据是否已经被筛选过
					if n["Index"] == k then
						bFlag = false
						break
					end
				end
			end
			
			if nDataChance > v and bFlag then
				nDataChance = v
				nDataIndex = k
			end
		end
		
		tData[i] = {}
		tData[i]["Index"] = nDataIndex
		tData[i]["Chance"] = nDataChance
	end
	
	--保存如果概率被减成负值的所补足的值
	local nAdd = 0
	
	--所有奖励概率值根据贵重物品的概率调整变化,调整后保存到tAwardChange表返回
	for i = 1, nCount do
		local nAwardIndex = tData[i]["Index"]
		local nAwardChance = tData[i]["Chance"]
		
		local bPreciousFlag = false
		local nNowPreciousChange = 0
		
		--判断当前索引是不是贵重物品
		for k,v in pairs(tNowPreciousIndex) do
			if k == nAwardIndex then
				bPreciousFlag = true
				nNowPreciousChange = v
				break
			end
		end
		
		--如果是贵重物品则直接从贵重物品表提取数据，否则需要计算概率
		if bPreciousFlag then
			tAwardChange[nAwardIndex] = nNowPreciousChange
		else
			--记录临时增加的数值
			local nTemp = 0
			
			if nChangeLeft ~= 0 then
				nTemp = nAwardChance + nEveryChange + nChangeLeft
			else
				nTemp = nAwardChance + nEveryChange
			end
			
			nTemp = nTemp + nAdd
			
			if nTemp < 0 then
				nAdd = nTemp
				nTemp = 0
			else
				nAdd = 0
			end
			
			tAwardChange[nAwardIndex] = nTemp
			
			nChangeLeft = 0
		end
	end
	
	return tAwardChange
end

--获得奖励详细信息
function Melter_GetRewordMsg(tAward)
	local sTalk = ""
	
	if tAward["RewardItem"] == nil then
		return sTalk
	end
	
	local tStr = Sys_Split(tAward["RewardItem"][1]["Attr"], " ")
	local nTime = tStr[4]
	local nNum = tStr[2]
	local nMonopoly = tStr[3]
	
	--时效
	if nTime ~= nil then
		sTalk = string.format(tLuaRes[10026],sTalk,math.floor(tonumber(nTime) / 1440),tRewardTemplate_Text["Prescript"])
	end
	
	--物品名
	sTalk = string.format(tLuaRes[10025],sTalk,Get_ItemtypeName(tAward["RewardItem"][1]["Id"]))
	
	--是否赠品
	if nMonopoly ~= nil and tonumber(nMonopoly) == 3 then
		sTalk = string.format(tLuaRes[10025],sTalk,tRewardTemplate_Text["Gift"])
	end
	
	--个数
	if nNum ~= nil and tonumber(nNum) > 1 then
		sTalk = string.format(tLuaRes[10026],sTalk,tRewardTemplate_Text["Number"],tonumber(nNum))
	end
	
	return sTalk
end

--奖励通用接口
function Melter_Reward(nCostType, nValue, nMonopoly, nNowUserId)
	local nUserId = nNowUserId or Get_UserId()
	
	local nMonopolyIndex = 0
	
	if nMonopoly == 0 then
		--熔炼的物品非赠配1
		nMonopolyIndex = 1
	else
		--赠品配2
		nMonopolyIndex = 2
	end
	
	local tAward = CommonFunc_Copy(tMelter_Info["Reword"][nCostType][nValue])
	local tFirstAward = CommonFunc_Copy(tMelter_Info_First["Reword"][nCostType][nValue])
	local tOverAward = CommonFunc_Copy(tMelter_Info_Over["Reword"][nCostType][nValue])
	
	--判断是否无赠品服务器
	-- if SpecialServer_ChkNoGiftServer() then
		-- tAward = CommonFunc_Copy(tMelter_Info_NoGift["Reword"][nCostType][nValue])
		-- tFirstAward = CommonFunc_Copy(tMelter_Info_NoGift_First["Reword"][nCostType][nValue])
		-- tOverAward = CommonFunc_Copy(tMelter_Info_NoGift_Over["Reword"][nCostType][nValue])
	-- end
	
	--抽奖次数
	local nMelter_Data = 0
	
	if tAward[nMonopolyIndex]["StcEvent"] ~= nil and tAward[nMonopolyIndex]["StcType"] ~= nil then
		local nMelter_Event = tAward[nMonopolyIndex]["StcEvent"]
		local nMelter_Type = tAward[nMonopolyIndex]["StcType"]
		
		--是否清零
		if (tAward[nMonopolyIndex]["StcDelay"] ~= nil) and (tAward[nMonopolyIndex]["StcTimeType"] ~= nil) then
			Task_StcReset(nMelter_Event,nMelter_Type,nUserId,tAward[nMonopolyIndex]["StcTimeType"],tAward[nMonopolyIndex]["StcDelay"])
		end
		
		nMelter_Data = Get_UserStatisticValue(nMelter_Event,nMelter_Type,nUserId)
	end
	
	--判断是否已经达到抽奖次数上限
	local bMelter_Over = false
	
	if tOverAward ~= nil then
		if tOverAward[nMonopolyIndex] ~= nil then
			if tOverAward[nMonopolyIndex]["LogFile"] == nil then
				tOverAward[nMonopolyIndex]["LogFile"] = "Melter"
			end
			
			if tAward[nMonopolyIndex]["StcEvent"] ~= nil and tAward[nMonopolyIndex]["StcType"] ~= nil then
				local nMelter_Limit = tAward[nMonopolyIndex]["StcLimit"] or 0
				
				if nMelter_Data >= nMelter_Limit then
					bMelter_Over = true
				end
			end
		end
	end
	
	--判断是否有配首抽奖励
	local bFirst = false
	
	if tFirstAward ~= nil then
		if tFirstAward[nMonopolyIndex] ~= nil then
			if tAward[nMonopolyIndex]["StcEvent"] ~= nil and tAward[nMonopolyIndex]["StcType"] ~= nil then
				-- local nEvent = tAward[nMonopolyIndex]["StcEvent"]
				-- local nType = tAward[nMonopolyIndex]["StcType"]				
				-- local nData = Get_UserStatisticValue(nEvent,nType,nUserId)
				
				--判断是不是第一次抽奖
				if nMelter_Data <= 0 then
					bFirst = true
				end
			end
		end
	end
	
	--保存权重
	local nGlobalId = tAward[nMonopolyIndex]["GlobalId"] or 0
	local nPos = tAward[nMonopolyIndex]["Pos"] or 0
	local nData = 0
	--基础点数
	local nBasic = 10
	
	--权重概率调整
	if nGlobalId ~= 0 and (not bFirst) then
		--超过1050后  贵重物品几率 每10点上升1
		local nLimitMax = 1050
		--小于950后  贵重物品几率 每10点下降1
		local nLimitMin = 950
		--获取动态表基础值
		nData = Get_SysDynaGlobalData(nGlobalId,nPos)
		
		--计算浮动值
		local nTemp = 0
		local nAdd = 0
		
		if nData > nLimitMax then
			nTemp = nData - nLimitMax
			nAdd = math.floor(nTemp / nBasic)
		elseif nData < nLimitMin then
			nTemp = nLimitMin - nData
			nAdd = math.floor(nTemp / nBasic) * (-1)
		end
		
		--贵重物品索引
		local tPreciousIndex = {}
		--随机奖励物品种类统计
		local nCount = 0
		
		for k,v in pairs(tAward[nMonopolyIndex]) do
			if type(v) == "table" then
				nCount = nCount + 1
				if v["Precious"] == 1 then
					--保存贵重物品概率修改值
					tPreciousIndex[k] = v["ItemChance"] + (nAdd * tAward[nMonopolyIndex]["ItemChanceSum"] / 1000)
				end
			end
		end
		
		--保存每个物品的概率调整后的数值
		-- local tAwardChange = Melter_RandomCompute(tAward[nMonopolyIndex], tPreciousIndex, nCount, nUserId)
		
		-- for i = 1, nCount do
			-- tAward[nMonopolyIndex][i]["ItemChance"] = math.floor(tAwardChange[i])
		-- end
	end
	
	--抽奖次数增加
	if tAward[nMonopolyIndex]["StcEvent"] ~= nil and tAward[nMonopolyIndex]["StcType"] ~= nil then
		local nEvent = tAward[nMonopolyIndex]["StcEvent"]
		local nType = tAward[nMonopolyIndex]["StcType"]
		
		Task_AddStatistic(nEvent,nType,1,1,nUserId)
	end
	
	local flat = 0
	local tAwardResult = {}
	local sRewardStr = ""
	
	--如果是首抽则直接置为首抽奖池
	if bFirst then
		tAward = CommonFunc_Copy(tFirstAward)
	end
	
	--如果是已经达到抽奖次数上限则走上限后的奖池
	if bMelter_Over then
		tAward = CommonFunc_Copy(tOverAward)
	end
	
	--判断玩家性别
	local nSex = Get_UserSex(nUserId)
	
	--是女性玩家则鲜花转情书
	if tMelter_Flower[nSex] ~= nil then
		for k,v in pairs(tAward[nMonopolyIndex]) do
			if type(v) == "table" then
				local nFlowerItem = v["RewardItem"][1]["Id"]
				
				if nFlowerItem ~= nil then
					if tMelter_Flower[nSex][nFlowerItem] ~= nil then
						tAward[nMonopolyIndex][k]["RewardItem"][1]["Id"] = tMelter_Flower[nSex][nFlowerItem][1]
						tAward[nMonopolyIndex][k]["ActionId"] = tMelter_Flower[nSex][nFlowerItem][2][nMonopolyIndex]
					end
				end
			end
		end
	end
	
	--判断背包是否已满
	local nSpace = RewardTemplate_GetRandomSpace(tAward,nMonopolyIndex,nUserId)
	
	--背包满，发邮件
	if nSpace > 0 and (not User_CheckLeftSpace(nSpace,nUserId)) then
		flat,tAwardResult = Probabil_RandomAward(tAward,nMonopolyIndex)
		
		local nActionId = tAwardResult[1]["tAward"][1]["ActionId"] or 0
		
		--判断是否有限量配置（全服）
		if tAwardResult[1]["tAward"][1]["GlobalId"] ~= nil then
			local nLimitGlobalId = tAwardResult[1]["tAward"][1]["GlobalId"]
			local nLimitPos = tAwardResult[1]["tAward"][1]["Pos"] or 0
			local nLimitData = tAwardResult[1]["tAward"][1]["MaxData"] or 1
			local nFullIndex = tAwardResult[1]["tAward"][1]["FullIndex"] or 1
			local nNowGlobalData = Get_SysDynaGlobalData(nLimitGlobalId,nLimitPos)
			
			--达到限量，修改奖励索引
			if nNowGlobalData >= nLimitData then
				nActionId = tAward[nMonopolyIndex][nFullIndex]["ActionId"] or 0
				tAwardResult[1]["tAward"][1]["Precious"] = tAward[nMonopolyIndex][nFullIndex]["Precious"] or 0
				tAwardResult[1]["tAward"][1]["RewardItem"][1]["Id"] = tAward[nMonopolyIndex][nFullIndex]["RewardItem"][1]["Id"]
				tAwardResult[1]["tAward"][1]["RewardItem"][1]["Attr"] = tAward[nMonopolyIndex][nFullIndex]["RewardItem"][1]["Attr"]
			else
				Sys_SetSynaGlobalData(nLimitGlobalId,nLimitPos,nNowGlobalData + 1)
			end
		end
		
		--判断是否有限量配置（个人）
		if tAwardResult[1]["tAward"][1]["EventType"] ~= nil and tAwardResult[1]["tAward"][1]["DataType"] ~= nil then
			local nLimitEvent = tAwardResult[1]["tAward"][1]["EventType"]
			local nLimitType = tAwardResult[1]["tAward"][1]["DataType"]
			local nLimitData = tAwardResult[1]["tAward"][1]["RewardData"]
			local nLimitDelay = tAwardResult[1]["tAward"][1]["RewardDelay"]
			local nLimitTimeType = tAwardResult[1]["tAward"][1]["RewardTimeType"]
			local nFullIndex = tAwardResult[1]["tAward"][1]["FullIndex"] or 1
			
			--是否清零
			if (nLimitDelay ~= nil) and (nLimitTimeType ~= nil) then
				Task_StcReset(nLimitEvent,nLimitType,nUserId,nLimitTimeType,nLimitDelay)
			end
			
			local nNowLimitData = Get_UserStatisticValue(nLimitEvent,nLimitType,nUserId)
			
			if nNowLimitData >= nLimitData then
				nActionId = tAward[nMonopolyIndex][nFullIndex]["ActionId"] or 0
				tAwardResult[1]["tAward"][1]["Precious"] = tAward[nMonopolyIndex][nFullIndex]["Precious"] or 0
				tAwardResult[1]["tAward"][1]["RewardItem"][1]["Id"] = tAward[nMonopolyIndex][nFullIndex]["RewardItem"][1]["Id"]
				tAwardResult[1]["tAward"][1]["RewardItem"][1]["Attr"] = tAward[nMonopolyIndex][nFullIndex]["RewardItem"][1]["Attr"]
			else
				Task_AddStatistic(nLimitEvent,nLimitType,1,1,nUserId)
				Task_SetStcTimestamp(nLimitEvent,nLimitType,0,nUserId)
			end
		end
		
		--邮件发
		local sSender = tMelter_Text["Mail"]["Sender"]
		local sTitle = tMelter_Text["Mail"]["Title"]
		local sContent =tMelter_Text["Mail"]["Content"]
		
		Sys_SendMail(nUserId,0,0,nActionId,0,30,sSender,sTitle,sContent)
		
		sRewardStr = Melter_GetRewordMsg(tAwardResult[1]["tAward"][1])
		
		--提示
		-- User_TalkChannel2005(string.format(tRewardTemplate_Text["Currency"], sRewardStr), nUserId)
	else
		--直接给
		tAwardResult, sRewardStr = RewardTemplate_NewRandomNoTip(tAward,nMonopolyIndex,nUserId)
	end
	
	--接入[英文征服][活动脚本]5月熔炼炉回收（5.26-6.08）逻辑
	SmeltingRecovery_MelterLink(nCostType, nValue, nMonopoly, nUserId)
	
	--是否全服公告
	if tAwardResult[1]["tAward"][1]["Precious"] ~= nil and tAwardResult[1]["tAward"][1]["Precious"] == 1 then
		local sUserName = Get_UserName(nUserId)
		local nAwardItemId = tAwardResult[1]["tAward"][1]["RewardItem"][1]["Id"]
		
		--判断是否稀有神纹
		local bRune = false
		
		for k,v in pairs(tMelter_Cont["RuneId"]) do
			if nAwardItemId == v then
				bRune = true
				break
			end
		end
		
		if bRune then
			sRewardStr = string.format(tLuaRes[10025],tMelter_Text["BroadCast"]["NewRune"],sRewardStr)
		end
		
		--判断是否新法器
		local bImplement = false
		
		for k,v in pairs(tMelter_Cont["ImplementId"]) do
			if nAwardItemId == v then
				bImplement = true
				break
			end
		end
		
		if bImplement then
			sRewardStr = string.format(tLuaRes[10025],tMelter_Text["BroadCast"]["NewImplement"],sRewardStr)
		end
		
		local sItemName = ""
		
		if nCostType == 8 then
			sItemName = Get_ItemtypeName(nValue)
		end
		
		local sSetBroadCast = ""
		-- 判断是否有配置自己的公告
		if tAwardResult[1]["tAward"][1]["BroadCast"] ~= nil then
			sSetBroadCast = tAwardResult[1]["tAward"][1]["BroadCast"]
		else
			sSetBroadCast = tMelter_Text["BroadCast"]["Result"]
		end
		
		local sBroadCast = string.format(sSetBroadCast, sUserName, sItemName,sRewardStr)
		
		Sys_TalkBroadcast(sBroadCast)
	end
	
	--有权重配置
	-- if nGlobalId ~= 0 and (not bFirst)then
		-- --计算最终的值存入动态表
		-- nData = nData + nBasic + (tAwardResult[1]["tAward"][1]["AddNum"] or 0)
		
		-- Sys_SetSynaGlobalData(nGlobalId,nPos,nData)
	-- end
	
	--判断是否有额外的奖励
	if tMelter_Info["RewordExtra"][nCostType] ~= nil then
		if tMelter_Info["RewordExtra"][nCostType][nValue] ~= nil then
			if tMelter_Info["RewordExtra"][nCostType][nValue][nMonopolyIndex] ~= nil then
				RewardTemplate_UseItemAndMsg(tMelter_Info["RewordExtra"][nCostType][nValue][nMonopolyIndex],nUserId)
			end
		end
	end
	
	return tAwardResult[1]["tAward"][1]
end

--返回结果数据
function Melter_ResultReturn(tAward)
	local nType = 0
	local nValue = 0
	local nNum = 0
	local nMonopoly = 0
	local nPrecious = tAward["Precious"] or 0
	
	--获得物品
	if tAward["RewardItem"] ~= nil then
		nType = 8
		nValue = tAward["RewardItem"][1]["Id"]
		
		local tStr = Sys_Split(tAward["RewardItem"][1]["Attr"], " ")
		local nAttr = 0
		
		--提取物品属性
		if tStr[3] ~= nil then
			nAttr = tonumber(tStr[3])
		end
		
		if nAttr == 3 then
			nMonopoly = 1
		end
		
		nNum = tonumber(tStr[2])
		
	--获得金币
	elseif tAward["RewardMoney"] ~= nil then
		nType = 1
		nValue = tAward["RewardMoney"]["Value"]
	--获得天石
	elseif tAward["RewardEMoney"] ~= nil then
		nType = 2
		nValue = tAward["RewardEMoney"]["Value"]
	--获得赠点
	elseif tAward["RewardEMoneyMono"] ~= nil then
		nType = 3
		nValue = tAward["RewardEMoneyMono"]["Value"]
	--获得赛马积分
	elseif tAward["RewardRidingPoint"] ~= nil then
		nType = 4
		nValue = tAward["RewardRidingPoint"]["Value"]
	--获得气力值
	elseif tAward["RewardStrengthValue"] ~= nil then
		nType = 5
		nValue = tAward["RewardStrengthValue"]["Value"]
	--获得黄金积分
	elseif tAward["RewardGoldenLeague"] ~= nil then
		nType = 6
		nValue = tAward["RewardGoldenLeague"]["Value"]
	--获得修为值
	elseif tAward["RewardRepairValue"] ~= nil then
		nType = 7
		nValue = tAward["RewardRepairValue"]["Value"]
	end
	
	return nType, nValue, nMonopoly, nPrecious, nNum
end

--单抽
function Melter_Extract(nUserId, nCostType, nValue, nMonopoly)
	-- 判断玩家是否在跨服状态下
	if User_IsUserToCross(nUserId) then
		return
	end
	
	--判断玩家当前是否是死亡状态
	local nLife = Get_UserLife(nUserId)
	
	if nLife <= 0 then
		Sys_MsgBox(tMelter_Text["MsgBox"]["Die"],nil,nil,nUserId)
		return
	end
	
	--服务器判断
	if tMelter_Info["Reword"][nCostType][nValue]["LimitUseGlobal"] ~= nil then
		local nGlobalId = tMelter_Info["Reword"][nCostType][nValue]["LimitUseGlobal"]
		if Get_SysDynaGlobalData(nGlobalId,0) < 1 then
			Sys_MsgBox(tMelter_Text["MsgBox"]["NewLimit"],nil,nil,nUserId)
			return
		end
	end
	
	--前置条件判断
	if not Melter_Judge(nCostType, nValue, nMonopoly, 0, nUserId) then
		return
	end
	
	--获得奖励
	local tAward = Melter_Reward(nCostType, nValue, nMonopoly, nUserId)
	--获取结果数据
	local nResultType, nResultValue, nResultMonopoly, nPrecious, nResultNum = Melter_ResultReturn(tAward)
	
	--结果返回
	User_MelterResult(nResultType, nResultValue, nResultMonopoly, nPrecious, nResultNum, nUserId)
end

--十连抽
function Melter_TenExtract(nUserId, nCostType, nValue, nMonopoly)
	-- 判断玩家是否在跨服状态下
	if User_IsUserToCross(nUserId) then
		return
	end

	--判断玩家当前是否是死亡状态
	local nLife = Get_UserLife(nUserId)
	
	if nLife <= 0 then
		Sys_MsgBox(tMelter_Text["MsgBox"]["Die"],nil,nil,nUserId)
		return
	end
	
	--服务器判断
	if tMelter_Info["Reword"][nCostType][nValue]["LimitUseGlobal"] ~= nil then
		local nGlobalId = tMelter_Info["Reword"][nCostType][nValue]["LimitUseGlobal"]
		if Get_SysDynaGlobalData(nGlobalId,0) < 1 then
			Sys_MsgBox(tMelter_Text["MsgBox"]["NewLimit"],nil,nil,nUserId)
			return
		end
	end
	
	--前置条件判断
	if not Melter_Judge(nCostType, nValue, nMonopoly, 1, nUserId) then
		return
	end
	
	local sTemp = "%d-%d-%d-%d-%d"
	local sResult = ""
	
	for i = 1, 10 do
		--获得奖励
		local tAward = Melter_Reward(nCostType, nValue, nMonopoly, nUserId)
		--获取结果数据
		local nResultType, nResultValue, nResultMonopoly, nPrecious, nResultNum = Melter_ResultReturn(tAward)
		--保存结果数据
		if i == 10 then
			sResult = sResult..string.format(sTemp, nResultType, nResultValue, nResultMonopoly, nPrecious, nResultNum)
		else
			sResult = sResult..string.format(sTemp, nResultType, nResultValue, nResultMonopoly, nPrecious, nResultNum).." "
		end
	end
	
	--结果返回
	User_TenMelterResult(sResult, nUserId)
end

--隔天清限量物品动态码值
function Melter_GlobalDataReset()
	local nGlobalId = tMelter_Cont["TotalGlobalId"]
	if Get_SysDynaGlobalData1(nGlobalId) > 0 then
		return
	end
	
	Sys_SetSynaGlobalData1(nGlobalId,1)
	
	--每天清零
	for k,v in pairs(tMelter_Cont["GlobalId"]) do
		Sys_ResetAllSynaGlobalData(v)
	end
end

function Melter_GlobalDataResetToZero()
	local nGlobalId = tMelter_Cont["TotalGlobalId"]
	
	Sys_SetSynaGlobalData1(nGlobalId,0)
end

--每小时重置
function Melter_GlobalDataResetEveryHour()
	local nGlobalId = tMelter_Cont["HourGlobalId"]
	if Get_SysDynaGlobalData0(nGlobalId) > 0 then
		return
	end
	
	Sys_SetSynaGlobalData0(nGlobalId,1)
	
	Sys_SetSynaGlobalData1(nGlobalId,0)
	
	for k,v in pairs(tMelter_Cont["HourGlobalIdFox"]) do
		Sys_ResetAllSynaGlobalData(v)
	end
end

function Melter_GlobalDataResetToZeroEveryHour()
	local nGlobalId = tMelter_Cont["HourGlobalId"]
	
	Sys_SetSynaGlobalData0(nGlobalId,0)
end

